'use strict';

function ownObject(value, key) {
  return value !== null && typeof value === 'object' && !Array.isArray(value) && Object.prototype.hasOwnProperty.call(value, key);
}

function validateBuildPolicy(policy) {
  if (!ownObject(policy, 'engine') || policy.engine !== 'node') {
    throw new Error('engine must be node');
  }
  if (!ownObject(policy, 'targets') || !Array.isArray(policy.targets) || !policy.targets.includes('server') || !policy.targets.includes('browser')) {
    throw new Error('targets must include server and browser');
  }
  if (!ownObject(policy, 'checks') || !Array.isArray(policy.checks) || !policy.checks.includes('format') || !policy.checks.includes('unit')) {
    throw new Error('checks must include format and unit');
  }
  if (!ownObject(policy, 'options') || !ownObject(policy.options, 'strict') || !policy.options.strict) {
    throw new Error('strict mode must be enabled');
  }
  if (!ownObject(policy, 'metadata') || !ownObject(policy.metadata, 'mode') || policy.metadata.mode !== 'automatic') {
    throw new Error('metadata mode must be automatic');
  }
  return true;
}

module.exports = { validateBuildPolicy };

