'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api), ['validateBuildPolicy']);
const { validateBuildPolicy } = api;

const valid = {
  engine: 'node',
  targets: ['browser', 'server', 'server', 'worker'],
  checks: ['unit', 'format', 'lint', 'unit'],
  options: { strict: true },
  metadata: { mode: 'automatic' }
};
const before = JSON.stringify(valid);
assert.equal(validateBuildPolicy(valid), true);
assert.equal(JSON.stringify(valid), before);

function failure(policy, message) {
  assert.throws(
    () => validateBuildPolicy(policy),
    error => error instanceof Error && error.message === message
  );
}

failure(null, 'engine must be node');
failure([], 'engine must be node');
failure({}, 'engine must be node');
failure({ engine: 'NODE' }, 'engine must be node');
failure({ engine: 'node', targets: null }, 'targets must include server and browser');
failure({ engine: 'node', targets: ['server'] }, 'targets must include server and browser');
failure({ engine: 'node', targets: ['server', 'browser'], checks: 'format,unit' }, 'checks must include format and unit');
failure({ engine: 'node', targets: ['server', 'browser'], checks: ['format'] }, 'checks must include format and unit');
failure({
  engine: 'node',
  targets: ['server', 'browser'],
  checks: ['format', 'unit'],
  options: null
}, 'strict mode must be enabled');
failure({
  engine: 'node',
  targets: ['server', 'browser'],
  checks: ['format', 'unit'],
  options: { strict: 1 },
  metadata: { mode: 'automatic' }
}, 'strict mode must be enabled');
failure({
  engine: 'node',
  targets: ['server', 'browser'],
  checks: ['format', 'unit'],
  options: { strict: true },
  metadata: null
}, 'metadata mode must be automatic');
failure({
  engine: 'node',
  targets: ['server', 'browser'],
  checks: ['format', 'unit'],
  options: { strict: true },
  metadata: { mode: 'manual' }
}, 'metadata mode must be automatic');

const inheritedEngine = Object.create({ engine: 'node' });
inheritedEngine.targets = ['server', 'browser'];
inheritedEngine.checks = ['format', 'unit'];
inheritedEngine.options = { strict: true };
inheritedEngine.metadata = { mode: 'automatic' };
failure(inheritedEngine, 'engine must be node');

const inheritedStrict = Object.create({ strict: true });
failure({
  engine: 'node',
  targets: ['server', 'browser'],
  checks: ['format', 'unit'],
  options: inheritedStrict,
  metadata: { mode: 'automatic' }
}, 'strict mode must be enabled');

failure({
  engine: 'wrong',
  targets: [],
  checks: [],
  options: {},
  metadata: {}
}, 'engine must be node');

